mapper.select:
SELECT USER_ID, USER_NAME, USER_PSWD, USER_MAIL, JOIN_DATE, USER_STATUS, POINT_BALANCE
FROM USER_MASTER
WHERE USER_ID = #{userId}

mapper.update:
UPDATE USER_MASTER
SET USER_STATUS = #{userStatus}
WHERE USER_ID = #{userId}

UPDATE USER_MASTER
SET USER_PSWD = #{userPswd}
WHERE USER_ID = #{userId}

UPDATE USER_MASTER
SET USER_NAME = #{userName}
WHERE USER_ID = #{userId}

UPDATE USER_MASTER
SET POINT_BALANCE = POINT_BALANCE + #{amount}
WHERE USER_ID = #{userId}

UPDATE USER_MASTER
SET POINT_BALANCE = POINT_BALANCE - #{amount}
WHERE USER_ID = #{userId}
  AND POINT_BALANCE >= #{amount}

mapper.select:
SELECT COUNT(*)
FROM USER_MASTER
WHERE USER_MAIL = #{userMail}
